#nullable enable
using UnityEngine;
using System.Reflection;
using DrakeModsLibs.Forge;

namespace DrakesItemShop.JuteMat.Items;

internal static class DeerMat
{
    private static Assembly Owner => typeof(DeerMat).Assembly;

    public const string Id = "Drake_DeerMat";

    internal static void Build(Transform parent, float scale = 1f)
    {
    }

    // Visual scale of the 2 m jutemat mesh. Deer hide cutout doesn't fill the square UV,
    // so collision/Half stay a bit smaller than the mesh so the hover bound matches the hide.
    private const float VisualScale = 0.72f;
    private const float Bound = 0.72f; // half-extent ≈ hide silhouette

    internal static void Dress(GameObject prefab)
    {
        ForgeLook.Model(Owner, prefab, "models/jutemat.glb");
        ForgeLook.CollisionBox(prefab, new Vector3(0f, 0.04f, 0f), new Vector3(Bound * 2f, 0.08f, Bound * 2f));
        ForgeLook.Material(prefab, "Fabric", null, "jute_carpet", "jute_carpet", null, null);
        global::DrakesItemShop.Pieces.RugFabric.Apply(prefab, "jute_carpet", "rug_deer", "deerhide_rug");

        if (prefab.GetComponent<global::Container>() is { } c0)
        {
            c0.m_width = 4;
            c0.m_height = 1;
        }
        if (prefab.GetComponent<global::Piece>() is { } c1)
        {
            c1.m_allowRotatedOverlap = true;
            c1.m_notOnTiltingSurface = false;
        }
        if (prefab.GetComponent<global::WearNTear>() is { } c2)
        {
            c2.m_burnable = true;
            c2.m_supports = false;
            c2.m_health = 200f;
        }

        foreach (var t in prefab.GetComponentsInChildren<Transform>(true))
        {
            if (t.name == "forge_visual")
                t.localScale = Vector3.one * VisualScale;
        }

        ForgeLook.SnapPoints(prefab, true,
            new Vector3(-Bound, 0f, -Bound), new Vector3(-Bound, 0f, Bound),
            new Vector3(Bound, 0f, -Bound), new Vector3(Bound, 0f, Bound));
    }
}
